-- Hyprland configuration main entry point.
-- Loads monitors, Orbit presentation settings, and session lifecycle.
--
-- Border and group colours are applied by Noctalia's generated hyprland.lua template.
--
-- Theme colours are regenerated by Noctalia's configured templates.
--
-- Keybindings follow the CachyOS Hyprland (cachyos-hypr-noctalia) defaults so a
-- fresh CachyOS install keeps its original binds; see docs/keybinds.md.

local home = os.getenv("HOME")
package.path = home .. "/.config/hypr/?.lua;" .. package.path

-- Default applications. The upper-case names mirror the CachyOS
-- config/variables.lua contract; the values are Orbit's application choices.
TERMINAL     = "wezterm"
FILE_MANAGER = "nautilus"
BROWSER      = "zen-browser"
EDITOR       = "zeditor"
CALCULATOR   = "gnome-calculator"
TASK_MANAGER = "missioncenter"

-- Workspaces bound per monitor by the numeric binds. Orbit allocates Home
-- workspaces in five-workspace blocks per monitor (orbit-home-workspaces).
NUM_WPM = 5

-- Prefix for application launches. Orbit is validated with the plain
-- "Hyprland" session entry; when starting through UWSM use "uwsm app -- ".
local launchPrefix = ""

-- Application launcher paths: terminal, file manager, app menu, utility scripts.
local terminal = TERMINAL
local fileManager = FILE_MANAGER
local noctCall = "noctalia msg "
local launcher = noctCall .. "panel-toggle launcher"
local chatGPT = "chatgpt"
local openCode = terminal .. " start --class orbit-opencode -- " .. home .. "/.opencode/bin/opencode"
local dailyNote = home .. "/.local/bin/orbit-daily-note"
local scratchpad = home .. "/.local/bin/orbit-scratchpad"
local scripts = home .. "/.config/hypr/scripts"
local gpuScreenRecorder = home .. "/.local/bin/gpu-screen-recorder-control"
local wallpaperSettings = home .. "/.local/bin/orbit-wallpaper-launcher"
local animateLock = scripts .. "/animate-lock"
local animateShutdown = scripts .. "/animate-shutdown"
local workspaceAltTab = home .. "/.local/bin/workspace-alt-tab"
local moveWindowWorkspace = scripts .. "/move-window-workspace"
local focusDirectional = scripts .. "/focus-directional"

-- Modifier key for all Hyprland keybindings.
local mainMod = "SUPER"

-- Third-party Hyprland plugins: Hyprglass (blur/glass effects) and HyprWindowShade (ripple animations).
local hyprGlassPlugin = home .. "/.local/share/hyprland/plugins/hyprglass.so"
local hyprWindowShadePlugin = home .. "/.local/share/hyprland/plugins/HyprWindowShade.so"
local scrollOverviewPlugin = home .. "/.local/share/hyprland/plugins/libscrolloverview.so"
local dynamicCursorsPlugin = home .. "/.local/share/hyprland/plugins/dynamic-cursors.so"

-- Compositor policy is maintained here; generated appearance adapters are not
-- configuration inputs.
local orbitAppearance = {
    shape = { corner_radius = 11, window_radius = 11 },
    transparency = { compositor = { active_opacity = 1.0, inactive_opacity = 0.95 } },
    effects = {
        hyprglass_enabled = true,
        hyprglass_blur_type = "glass",
        animations_enabled = true,
        animations = {
            global = { enabled = true, speed = 4.8, type = "default" },
            windows = { enabled = true, speed = 1.3, type = "slide" },
            fades = { enabled = true, speed = 1.1, type = "fade" },
            layers = { enabled = true, speed = 1.8, type = "fade" },
            workspaces = { enabled = true, speed = 1.1, type = "slidefadevert" },
            movement = { enabled = true, speed = 1.2, type = "slide" },
        },
    },
}
local orbitCursor = { theme = "oblique-cursor", size = 24 }
local hyprcursorTheme = "oblique-cursor"
local xcursorFallbackTheme = "Adwaita"
local cursorSize = orbitCursor.size or 24
local orbitShape = orbitAppearance.shape or { corner_radius = 10, window_radius = 10 }

local orbitFollowMouse = 2

-- Map Orbit animation style names to Hyprland animation parameters.
-- Orbit uses generic names (default, slidefadevert, popin); Hyprland needs full syntax.
local function animation_style(kind, fallback)
    if kind == "default" or kind == nil then return fallback end
    if kind == "slidefadevert" then return "slidefadevert -100%" end -- Vertical slide + fade
    if kind == "popin" then return "popin 80%" end                   -- Zoom-in effect at 80% start size
    return kind
end
-- Read dynamic lock screen background color from Orbit Wallpaper Engine.
-- The wallpaper shader generates hyprlock-background.conf with the current dominant color.
-- Fallback to hard-coded dark color if file does not exist.
local hyprlockBackgroundColor = "rgb(050508)"
local hyprlockBackgroundFile = io.open(home .. "/.cache/orbit-wallpaper-engine/hyprlock-background.conf", "r")
if hyprlockBackgroundFile then
    local contents = hyprlockBackgroundFile:read("*a")
    hyprlockBackgroundFile:close()
    local color = contents:match("color%s*=%s*rgb%((%x+)%)")
    if color then hyprlockBackgroundColor = "rgb(" .. color .. ")" end
end

-- Load the monitor layout generated by nwg-displays. A fresh machine has no
-- monitors.lua yet; fall back to auto-configuring every connected output so the
-- rest of this file still loads (a failed require aborts the whole config).
if not pcall(require, "monitors") then
    hl.monitor({ output = "", mode = "preferred", position = "auto", scale = "auto" })
end
-- The plugin's config namespace is unavailable during the initial parse. The
-- startup hook loads the plugin and performs a config-only reload afterward.
if hl.plugin.scrolloverview then
    require("scrolloverview")
end

-- Environment and permissions
-- These variables configure the look and behavior of Qt6 applications.
local function prepend_path_entry(path, entry)
    if (":" .. path .. ":"):find(":" .. entry .. ":", 1, true) then return path end
    return entry .. ":" .. path
end
local sessionPath = os.getenv("PATH") or "/usr/local/bin:/usr/bin"
sessionPath = prepend_path_entry(sessionPath, home .. "/bin")
sessionPath = prepend_path_entry(sessionPath, home .. "/.local/bin")
hl.env("PATH", sessionPath)                        -- Keep user tools discoverable in graphical and systemd scopes.
hl.env("HYPRCURSOR_THEME", hyprcursorTheme)        -- Canonical compositor/server-side cursor.
hl.env("HYPRCURSOR_SIZE", tostring(cursorSize))    -- Keep compositor and client cursor sizes aligned.
hl.env("XCURSOR_THEME", xcursorFallbackTheme)       -- Existing XCursor fallback for legacy clients.
hl.env("XCURSOR_SIZE", tostring(cursorSize))        -- X11 cursor compatibility adapter.
-- Allow hyprpm (Hyprland plugin manager) to load/unload plugins without sudo.
hl.permission("/usr/(bin|local/bin)/hyprpm", "plugin", "allow")

-- Session lifecycle: startup and shutdown hooks.

hl.on("hyprland.start", function()
    -- Only the explicit new-workspace application allowlist gets automatic
    -- workspace allocation. Ordinary windows are never routed by a daemon.
    -- Import the current session environment, start target-owned services once,
    -- run the login transition, and rebind the Hyprland portal after compositor
    -- readiness is confirmed.
    hl.exec_cmd(home .. "/.local/bin/orbit-session-bootstrap &")

    -- Start Noctalia from the graphical session so applications it launches
    -- inherit the active logind session rather than the user service cgroup.
    hl.exec_cmd("/usr/bin/noctalia &")

    -- Start the global-menu frontend after the Wayland compositor is ready.
    -- The executable is supplied by PATH, or by ORBIT_QUICKSHELL when a local
    -- installation is not on the graphical session PATH.
    local quickshell = os.getenv("ORBIT_QUICKSHELL") or "quickshell"
    hl.exec_cmd(quickshell .. " --config global-menu --no-duplicate &")

    -- Explicit orbit-game-run sessions own game-mode policy.

    -- Load plugins and refresh the compositor config. Sequence:
    -- 1. Reload hyprpm (plugin manager)
    -- 2. Load Hyprglass plugin (blur/glass effect)
    -- 3. Load HyprWindowShade plugin (ripple animations)
    -- 4. Brief sleep to allow plugin initialization
    -- 5. Reload config (pick up plugin availability)
    -- 6. Leave target-owned Orbit shell lifecycle under systemd
    hl.exec_cmd([[sh -c 'hyprpm reload 2>/dev/null || true; hyprctl plugin load ]] ..
    hyprGlassPlugin ..
    [[ 2>/dev/null || true; hyprctl plugin load ]] ..
     hyprWindowShadePlugin ..
     [[ 2>/dev/null || true; hyprctl plugin load ]] ..
     scrollOverviewPlugin ..
     [[ 2>/dev/null || true; hyprctl plugin load ]] ..
     dynamicCursorsPlugin .. [[ 2>/dev/null || true; sleep 0.5; hyprctl reload config-only']])
end)

-- Core behavior and appearance (window manager tuning).

hl.config({
    general = {
        gaps_in = 5,     -- Spacing between tiled windows (pixels).
        gaps_out = 20,   -- Spacing from windows to workspace edge (pixels).
        border_size = 2, -- Window border thickness (pixels).
        col = {
            -- Border colours are applied by Noctalia's generated theme template below.
        },
        resize_on_border = true,      -- Allow drag-resizing from window borders.
        extend_border_grab_area = 20, -- Enlarge the border grab area for easier resizing.
        allow_tearing = false,        -- Disable tear-free rendering (VSync enabled).
        layout = "master",            -- Use master layout: main + stack columns.
    },

    decoration = {
         rounding = orbitShape.window_radius or orbitShape.corner_radius,                          -- Compositor appearance policy.
        rounding_power = 2,                                                                       -- Curvature smoothness (2 = smoother).
        active_opacity = orbitAppearance.transparency.compositor.active_opacity,                  -- Active window opacity (1.0 = opaque).
        inactive_opacity = orbitAppearance.transparency.compositor.inactive_opacity,              -- Inactive window opacity (0.95 default).
        blur = { enabled = orbitAppearance.effects.hyprglass_enabled, new_optimizations = true }, -- Hyprglass blur if enabled.
        shadow = { enabled = true, range = 2, render_power = 5, color = 0xee1a1a1a },             -- Soft dark shadow beneath windows.
        motion_blur = { enabled = true, samples = 20 },
    },

    -- Global animation toggle (individual animations have their own enable flags).
    animations = { enabled = orbitAppearance.effects.animations_enabled },

    input = {
        kb_layout = "us",                      -- US keyboard layout.
        follow_mouse = orbitFollowMouse,       -- Follow mouse mode (0=off, 1=speed-1, 2=speed-2 from Orbit).
        mouse_refocus = false,                 -- Do not refocus windows when moving the mouse.
        sensitivity = 0,                       -- Mouse sensitivity (0 = use system default).
        touchpad = { natural_scroll = false }, -- Touchpad scroll direction (false = traditional).
    },

    cursor = {
        no_warps = true, -- Do not move cursor when switching windows (preserve position).
        sync_gsettings_theme = false, -- Keep Adwaita for XCursor/GTK while Hyprcursor uses Oblique.
    },

    misc = {
        force_default_wallpaper = 0,                -- Do not use Hyprland's default wallpaper.
        background_color = hyprlockBackgroundColor, -- Fallback background (from Orbit Wallpaper Engine or hard-coded).
        disable_hyprland_logo = true,               -- Hide "Hyprland" text splash.
        focus_on_activate = true,                   -- Focus windows when they request activation (e.g., notification clicks).
        animate_manual_resizes = true,              -- Animate window resizing when user drags.
        disable_splash_rendering = true,            -- Hide splash screen on startup.
    },

    -- CachyOS defaults: no update/donation nags, crisp XWayland on scaled outputs.
    ecosystem = { no_update_news = true, no_donation_nag = true },
    xwayland = { force_zero_scaling = true },

    binds = {
        window_direction_monitor_fallback = true, -- Allow focus to cross monitor boundaries with arrow keys.
        pass_mouse_when_bound = true,             -- Pass mouse events to windows even when a keybind is active.
    },

    -- Master layout: first window occupies a fixed main area on the left; subsequent windows stack on the right.
    -- This is ideal for a primary editor + auxiliary windows setup.
    master = {
        mfact = 0.7,                                 -- Main area factor (70% width for the main window).
        new_status = "slave",                        -- New windows start in the stack area, not main.
        orientation = "left",                        -- Main area on the left; stack on the right.
    },
    scrolling = { fullscreen_on_one_column = true }, -- Fullscreen if only one window in a column.
})

-- Dynamic cursor effects are optional so a missing or failed plugin never adds
-- unknown Hyprland configuration keys during the initial parse.
if hl.plugin.dynamic_cursors then
    hl.config({
        plugin = {
            dynamic_cursors = {
                enabled = true,
                mode = "tilt",
                shake = {
                    enabled = true,
                    threshold = 6.0,
                    base = 2.5,
                    speed = 3.0,
                    influence = 0.0,
                    limit = 4.0,
                    timeout = 1600,
                    effects = false,
                    ipc = false,
                },
                hyprcursor = {
                    enabled = true,
                    nearest = 0,
                    resolution = 192,
                    fallback = "clientside",
                },
            },
        },
    })
end


-- Hyprglass plugin: blur and glass effects for windows and layers.
-- Plugin is loaded dynamically on startup; only configure if present.
if hl.plugin.hyprglass then
    local hg = hl.plugin.hyprglass

    hg.config({
        default_theme = "dark",                                        -- Use dark theme (less bright refraction artifacts).
        default_preset = orbitAppearance.effects.hyprglass_blur_type,  -- Compositor-owned preset.
        -- Orbit layer-shell surfaces use native Hyprland blur. Hyprglass
        -- remains enabled for normal application windows.
        layers = { enabled = 0 },
    })

    -- "Glass" preset: high refraction and distortion for a glossy, transparent look.
    hg.preset("glass", {
        glass_opacity = 1,          -- Fully opaque glass (no extra transparency).
        blur_strength = 0.7,        -- Strong blur effect (0-1).
        blur_iterations = 3,        -- Number of blur passes (higher = more blur, more expensive).
        refraction_strength = 1,    -- Distortion from refraction (refracts light rays).
        chromatic_aberration = 0.5, -- Color separation at edges (0.5 = medium aberration).
        edge_thickness = 0.1,       -- Thickness of the refraction edge effect.
        lens_distortion = 0.9,      -- Barrel/pincushion distortion (0.9 = slight barrel).
        brightness = 1.1,           -- Brighten the blurred content slightly.
        contrast = 1.4,             -- Increase contrast (makes blurred content more visible).
    })
end

-- Animation curves: define timing functions for smooth motion.
-- Bezier curves: fast startup (ease-out), smooth middle (in-out), fast exit (quick).
-- Spring curve: adds bounce/overshoot for a more natural feel.
hl.curve("easeOutQuint", { type = "bezier", points = { { 0.23, 1 }, { 0.32, 1 } } })         -- Fast start, slow end.
hl.curve("easeInOutCubic", { type = "bezier", points = { { 0.65, 0.05 }, { 0.36, 1 } } })    -- Slow start/end, fast middle.
hl.curve("linear", { type = "bezier", points = { { 0, 0 }, { 1, 1 } } })                     -- Constant speed.
hl.curve("almostLinear", { type = "bezier", points = { { 0.5, 0.5 }, { 0.75, 1 } } })        -- Nearly constant, slight ease-in.
hl.curve("quick", { type = "bezier", points = { { 0.15, 0 }, { 0.1, 1 } } })                 -- Very fast (sharp acceleration).
hl.curve("easy", { type = "spring", mass = 1, stiffness = 71.2633, dampening = 15.8273644 }) -- Springy, bouncy motion.
hl.curve("orbitTunedB", { type = "spring", mass = 1, stiffness = 360, dampening = 22 })         -- Tuned motion/workspace spring.

-- Global animation timing (affects all animation speed multipliers).
hl.animation({ leaf = "global", enabled = orbitAppearance.effects.animations.global.enabled, speed = orbitAppearance
.effects.animations.global.speed, bezier = "default" })

-- Border color transitions when switching focus.
hl.animation({ leaf = "border", enabled = orbitAppearance.effects.animations.global.enabled, speed = 5.39, bezier =
"easeOutQuint" })

-- Window size/position changes. Use almostLinear to keep them smooth without fighting workspace transitions.
hl.animation({ leaf = "windows", enabled = orbitAppearance.effects.animations.windows.enabled, speed = orbitAppearance
.effects.animations.windows.speed, spring = "orbitTunedB" })

-- Disable windowsIn (new window entry animation) to prevent double-animation with fadeIn.
-- Client surface remains still; opacity fade alone provides entrance effect.
hl.animation({ leaf = "windowsIn", enabled = false, speed = 4.1, spring = "easy", style = animation_style(
orbitAppearance.effects.animations.windows.type, "popin 80%") })

-- Window exit animation (slide out on close).
hl.animation({ leaf = "windowsOut", enabled = true, speed = 2.95, spring = "orbitTunedB", style = animation_style(
orbitAppearance.effects.animations.windows.type, "slide") })

-- Opacity fade-in for new windows (entrance effect).
hl.animation({ leaf = "fadeIn", enabled = orbitAppearance.effects.animations.fades.enabled, speed = orbitAppearance
.effects.animations.fades.speed, bezier = "almostLinear" })

-- Opacity fade-out for closing windows.
hl.animation({ leaf = "fadeOut", enabled = true, speed = 1.25, bezier = "almostLinear" })

-- Generic fade transitions (dialogs, menus, etc.).
hl.animation({ leaf = "fade", enabled = orbitAppearance.effects.animations.fades.enabled, speed = 3.03, bezier = "quick" })

-- Layer animations (UI panels, notifications, OSD).
hl.animation({ leaf = "layers", enabled = orbitAppearance.effects.animations.layers.enabled, speed = orbitAppearance
.effects.animations.layers.speed, bezier = "easeOutQuint" })

-- Layer entrance animation (fade-in for panels).
hl.animation({ leaf = "layersIn", enabled = true, speed = 4, bezier = "easeOutQuint", style = animation_style(
orbitAppearance.effects.animations.layers.type, "fade") })

-- Layer exit animation (fade-out for panels).
hl.animation({ leaf = "layersOut", enabled = true, speed = 1.5, bezier = "linear", style = animation_style(
orbitAppearance.effects.animations.layers.type, "fade") })

-- Opacity fade for layers (additional effect on top of layersIn/Out).
hl.animation({ leaf = "fadeLayersIn", enabled = true, speed = 1.79, bezier = "almostLinear" })
hl.animation({ leaf = "fadeLayersOut", enabled = true, speed = 1.39, bezier = "almostLinear" })

-- Window movement (drag-to-move, layout adjustments).
hl.animation({ leaf = "windowsMove", enabled = orbitAppearance.effects.animations.movement.enabled, speed =
orbitAppearance.effects.animations.movement.speed, spring = "orbitTunedB", style = animation_style(
orbitAppearance.effects.animations.movement.type, "slide") })

-- Workspace transitions: use the pronounced ease-out curve in both directions so
-- the scene leaves decisively and settles visibly without bounce or overshoot.
hl.animation({ leaf = "workspaces", enabled = orbitAppearance.effects.animations.workspaces.enabled, speed =
orbitAppearance.effects.animations.workspaces.speed, spring = "orbitTunedB", style = animation_style(
orbitAppearance.effects.animations.workspaces.type, "slidefadevert -100%") })
hl.animation({ leaf = "workspacesIn", enabled = orbitAppearance.effects.animations.workspaces.enabled, speed = 2.45, spring =
"orbitTunedB", style = animation_style(orbitAppearance.effects.animations.workspaces.type, "slidefadevert -100%") })
hl.animation({ leaf = "workspacesOut", enabled = orbitAppearance.effects.animations.workspaces.enabled, speed = 2.0, spring =
"orbitTunedB", style = animation_style(orbitAppearance.effects.animations.workspaces.type, "slidefadevert -100%") })

-- Zoom factor: used for workspace overview or active indicator scaling.
hl.animation({ leaf = "zoomFactor", enabled = true, speed = 7, bezier = "quick" })

-- Keybindings
-- Keys and their meanings are the CachyOS Hyprland defaults
-- (/etc/skel/.config/hypr/config/binds.lua from cachyos-hypr-noctalia). Where
-- Orbit has a richer implementation of the same intent (directional focus and
-- movement, Alt-Tab, lock, wallpaper, task manager) the CachyOS key runs the
-- Orbit helper instead of the stock dispatcher. Orbit-only extras use keys the
-- CachyOS layout leaves free. See docs/keybinds.md for the full table.

-- AZERTY fix: the number-row keys emit symbols (& é " ' ...) without Shift, so
-- binding to the digit characters fails. Bind by physical keycode instead.
-- Digit d -> evdev keycode: 1..9 => 10..18, 0 => 19
local function digitCode(d)
    return "code:" .. (d == 0 and 19 or (9 + d))
end

-- Monitors are discovered at press time and ordered like orbit-home-workspaces
-- (left to right, then top to bottom), so MONITOR1/2/3 never name connectors.
local function sortedMonitors()
    local monitors = hl.get_monitors()
    table.sort(monitors, function(a, b)
        if a.x ~= b.x then return a.x < b.x end
        if a.y ~= b.y then return a.y < b.y end
        return a.name < b.name
    end)
    return monitors
end

local function focusMonitor(index)
    return function()
        local monitor = sortedMonitors()[index]
        if monitor then hl.dispatch(hl.dsp.focus({ monitor = monitor.name })) end
    end
end

local function moveWindowToMonitor(index)
    return function()
        local monitor = sortedMonitors()[index]
        if monitor then hl.dispatch(hl.dsp.window.move({ monitor = monitor.name })) end
    end
end

