hl.bind(mainMod .. " + ALT + C",    hl.dsp.exec_cmd(noctCall .. "panel-toggle session"))

-- Orbit applications on keys the CachyOS layout leaves free.
hl.bind(mainMod .. " + ALT + A",   hl.dsp.exec_cmd(chatGPT))    -- ChatGPT.
hl.bind(mainMod .. " + ALT + S",   hl.dsp.exec_cmd(openCode))   -- OpenCode in a dedicated terminal.
hl.bind(mainMod .. " + ALT + D",   hl.dsp.exec_cmd(dailyNote))  -- Today's daily note.
hl.bind(mainMod .. " + SHIFT + D", hl.dsp.exec_cmd(scratchpad)) -- Permanent scratchpad note.
hl.bind(mainMod .. " + M",         hl.dsp.exec_cmd(animateShutdown)) -- Confirmed logout with Orbit's exit choreography.

