---------------------------

-- Audio
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd(noctCall .. "volume-up"),   { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd(noctCall .. "volume-down"), { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd(noctCall .. "volume-mute"), { locked = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd(noctCall .. "mic-mute"),    { locked = true })

-- Media
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd(noctCall .. "media toggle"),   { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd(noctCall .. "media toggle"),   { locked = true })
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd(noctCall .. "media next"),     { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd(noctCall .. "media previous"), { locked = true })

-- Brightness
hl.bind("XF86MonBrightnessUp",   hl.dsp.exec_cmd(noctCall .. "brightness-up"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd(noctCall .. "brightness-down"), { locked = true, repeating = true })

-------------------
---- UTILITIES ----
-------------------

-- Screen Capture
hl.bind(mainMod .. " + P",     hl.dsp.exec_cmd("hyprpicker -a -n"))
hl.bind("Print",               hl.dsp.exec_cmd(noctCall .. "screenshot-region"))
hl.bind(mainMod .. " + Print", hl.dsp.exec_cmd(noctCall .. "screenshot-fullscreen"))

-- Screen recording (Orbit; GPU Screen Recorder)
hl.bind(mainMod .. " + SHIFT + R", hl.dsp.exec_cmd(gpuScreenRecorder .. " record")) -- Start/stop a recording.
hl.bind(mainMod .. " + SHIFT + Z", hl.dsp.exec_cmd(gpuScreenRecorder .. " replay")) -- Save the instant replay.

-- Theming and Wallpaper: the Orbit Wallpaper Engine settings window.
hl.bind(mainMod .. " + SHIFT + W", hl.dsp.exec_cmd(wallpaperSettings))

-- Clipboard
hl.bind(mainMod .. " + V", hl.dsp.exec_cmd(noctCall .. "panel-toggle clipboard"))

-- Notifications
hl.bind(mainMod .. " + A", hl.dsp.exec_cmd(noctCall .. "panel-toggle control-center notifications"))

-------------------------------
---- WORKSPACES & MONITORS ----
-------------------------------

-- Focus on monitors
for index = 1, 3 do
    hl.bind(mainMod .. " + " .. digitCode(index), focusMonitor(index))
end

-- Focus on workspace number
-- Absolute
for i = 1, NUM_WPM do
    local key = i % 10
    hl.bind(mainMod .. " + ALT + " .. digitCode(key), hl.dsp.focus({ workspace = i }))
end
-- Relative
for i = 1, NUM_WPM do
    local key = i % 10
    hl.bind(mainMod .. " + CONTROL + " .. digitCode(key), hl.dsp.focus({ workspace = "m~" .. i }))
end

-- Move to adjacent workspaces and next empty on a given monitor
hl.bind(mainMod .. " + CONTROL + Right", hl.dsp.focus({ workspace = "m+1" }))
hl.bind(mainMod .. " + CONTROL + Left",  hl.dsp.focus({ workspace = "m-1" }))
hl.bind(mainMod .. " + CONTROL + Down",  hl.dsp.focus({ workspace = "emptym" }))

-- Scroll through existing workspaces & monitors
hl.bind(mainMod .. " + mouse_down",           hl.dsp.focus({ workspace = "m-1" }))
hl.bind(mainMod .. " + mouse_up",             hl.dsp.focus({ workspace = "m+1" }))
hl.bind(mainMod .. " + CONTROL + mouse_up",   hl.dsp.focus({ workspace = "m-1" }))
hl.bind(mainMod .. " + CONTROL + mouse_down", hl.dsp.focus({ workspace = "m+1" }))

-- Special workspace (scratchpad)
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special" }))
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special())

-- Touchpad gestures (CachyOS defaults)
hl.gesture({ fingers = 4, direction = "horizontal", action = "workspace" })
hl.gesture({ fingers = 3, direction = "down",       action = "close" })
hl.gesture({ fingers = 3, direction = "up",         action = "fullscreen" })
hl.gesture({ fingers = 3, direction = "left",       action = "float" })

-- Window rules

-- Applications stay on the workspace where they were launched and float by default.
hl.window_rule({
    name = "default-floating",
    match = { class = ".*" },
    float = true,
})

-- Affinity is launched through XWayland, but remains usable in the normal
-- tiled layout instead of inheriting the generic floating default.
hl.window_rule({
    name = "affinity-tiled",
    match = { class = "^affinity\\.exe$", title = ".+", xwayland = true },
    float = false,
})

-- The only automatic workspace placement exceptions. The narrow event helper
-- allocates one normal workspace for these exact classes and nothing else.
for _, class in ipairs({ "^zen$", "^dev\\.zed\\.Zed$" }) do
    hl.window_rule({
        name = "new-workspace-app-" .. class,
        match = { class = class },
        float = false,
    })
end

-- Window rule: Steam games (full-screen optimizations).
-- Games are marked with content="game" to exclude them from game-mode detection and effects.
hl.window_rule({
    name = "steam-games",
    match = { class = "^steam_app_.*" },
    immediate = true,          -- Apply rule as soon as window is identified (not after mapping).
    no_anim = true,            -- Disable window animations (for smoother gameplay).
    no_blur = true,            -- Disable Hyprglass blur effects.
    no_shadow = true,          -- Disable drop shadow.
    decorate = false,          -- Hide window decorations (remove title bar).
    content = "game",          -- Mark as game content (used by game-mode detection).
    float = false,             -- Preserve normal tiled game clients; no workspace routing.
    no_follow_mouse = true,    -- Do not refocus when mouse moves (preserve game control).
    focus_on_activate = false, -- Do not auto-focus activation requests (reduce distractions).
})

-- Zed supplies its transparent chrome through the tracked theme; keep the
-- client surface fully opaque so only those internal surfaces reveal the
-- wallpaper.
-- Window rule: Zed code editor appearance.
-- Zed uses transparent chrome and tracks the Hyprland theme to show only internal surfaces.
-- Keep the client window opaque (no extra transparency from Hyprland).
hl.window_rule({
    name = "zed-appearance",
    match = { class = "^dev\\.zed\\.Zed$" },
    rounding = orbitShape.window_radius or orbitShape.corner_radius,
    no_shadow = true, -- Remove shadow (Zed provides its own).
})

-- Window rule: Obsidian note editor appearance.
-- Obsidian uses a similar tracked theme approach: transparent chrome, opaque editor.
-- Ensure consistent appearance with other modern applications.
hl.window_rule({
    name = "obsidian-appearance",
    match = { class = "^(obsidian|md\\.obsidian\\.Obsidian)$" },
    rounding = orbitShape.window_radius or orbitShape.corner_radius,
    decorate = false, -- Remove Hyprland decoration (Obsidian provides its own frame).
    no_shadow = true, -- No shadow (Obsidian renders its own if needed).
})

-- Window rule: Steam menu windows and popups (float).
-- Steam opens many transient windows (downloads, settings, etc.).
hl.window_rule({
    name = "steam-transient-windows",
    match = { class = "^steam$" },
    float = true, -- Float by default (main Steam window overridden below).
})

-- Window rule: Steam main window (keep tiled).
-- The main Steam window (title="Steam") should be tiled, not floated.
hl.window_rule({
    name = "keep-steam-main-window-tiled",
    match = { class = "^steam$", title = "^Steam$" },
    float = false,    -- Override: main window is tiled (respects layout manager).
    decorate = false, -- No window decoration (Steam provides its own UI).
})

-- Window rule: WezTerm terminal sizing.
hl.window_rule({
    name = "wezterm-sizing",
    match = { class = "^org\\.wezfurlong\\.wezterm$" },
    float = false,
    size = { 800, 600 },    -- Default new window size (wide for 80-col terminal + UI).
    center = true,          -- Center on current monitor.
    persistent_size = true, -- Remember size across launches.
})

-- Window rule: About This Computer Fastfetch terminal.
-- The launcher assigns this dedicated class so ordinary WezTerm windows are unaffected.
hl.window_rule({
    name = "orbit-about-sizing",
    match = { class = "^orbit-about$" },
    float = true,
    size = { 534, 262 },
})

-- Keep application keybind targets tiled on their current workspace.
hl.window_rule({
    name = "chatgpt-tiled",
    match = { class = "^Chatgpt$" },
    float = false,
})

hl.window_rule({
    name = "opencode-tiled",
    match = { class = "^orbit-opencode$" },
    float = false,
})

hl.window_rule({
    name = "orbit-notes-tiled",
    match = { class = "^orbit-notes$" },
    float = false,
})

-- Window rule: suppress maximize button events (disabled by default).
-- Some applications emit spurious maximize events; this rule can suppress them.
-- Currently disabled (set_enabled = false) to allow normal maximize behavior.
local suppressMaximizeRule = hl.window_rule({
    name = "suppress-maximize-events",
    match = { class = ".*" },
    suppress_event = "maximize",
})
suppressMaximizeRule:set_enabled(false) -- Disabled: let maximize work normally.

-- Layer rule: Noctalia UI elements (fallback theme bars, notifications, OSD).
-- NOCTALIA IS A FALLBACK: Only active if the primary Orbit shell fails to start or is disabled.
-- The Noctalia greeter provides basic window management, notifications, and panel when Orbit is unavailable.
-- When this layer matches, it indicates Orbit's shell/panel is not running (error condition).
hl.layer_rule({
    name = "noctalia",
    match = {
        namespace = "^noctalia-(bar-.+|notification|panel|osd|window-switcher)$",
    },
    no_anim = true,   -- Disable animations for fallback UI (lighter rendering = better fallback experience).
    ignore_alpha = 0.5, -- Ignore alpha < 0.5 (fade out effect without full animation opacity change).
})

-- Layer rule: Orbit's top panel (active primary UI).
-- Orbit's global menu grows downward from the panel. Disable animation on the panel's layer
-- or the menu will appear to slide in, breaking the integrated look.
hl.layer_rule({
    name = "orbit-top-panel-no-menu-animation",
    match = { namespace = "^orbit-top-panel$" },
    blur = false,
    no_anim = true, -- Panel resizes without animation (menu appears instantly integrated).
})

-- Native Hyprland owns Orbit menu blur.
hl.layer_rule({
    name = "orbit-menu-glass-native-blur",
    match = { namespace = "^orbit-menu-glass$" },
    blur = true,
    ignore_alpha = 0.01,
    no_anim = false,
})

hl.layer_rule({
    name = "orbit-workspace-indicators-native-blur",
    match = { namespace = "^orbit-workspace-indicators$" },
    blur = true,
    ignore_alpha = 0.01,
})

hl.layer_rule({
    name = "orbit-session-loading-native-blur",
    match = { namespace = "^orbit-session-loading$" },
    blur = true,
    ignore_alpha = 0.01,
})

hl.layer_rule({
    name = "orbit-overview-native-blur",
    match = { namespace = "^orbit-overview$" },
    blur = true,
    ignore_alpha = 0.01,
})

hl.window_rule({
    match = { class = "dev.noctalia.Noctalia" },
    float = true,
    size = { 1080, 920 },
})

hl.layer_rule({
    name = "noctalia",
    match = {
        namespace = "^noctalia-(bar-.+|notification|dock|panel|attached-panel|osd|window-switcher)$",
    },
    no_anim = true,
    ignore_alpha = 0.5,
    blur = false,
    blur_popups = false,
})

-- Noctalia's Hyprland template writes noctalia.lua; it does not exist until the
-- first templates-apply, so never let its absence abort this file.
pcall(function() require("noctalia").apply_theme() end)
